 * @method
 * @name btn_FileDown_3_onclick
 * @description btn_FileDown_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_3_onclick = function(e){
    try {
        fn_FileDown('' + dma_detail.get("contnId") + '','' + dma_detail.get("attachSeq3") + '','' + dma_detail.get("attachFileNm3") + ''); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst33011.btn_FileDown_3_onclick' }); }
