/**
 * @method
 * @name btn_FileDown_4_onclick
 * @description btn_FileDown_4 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_4_onclick = function(e){
    try {
        fn_FileDown('' + dma_detail.get("contnId") + '','' + dma_detail.get("attachSeq4") + '','' + dma_detail.get("attachFileNm4") + ''); return false;

