/**
 * @method
 * @name btn_closeDetail_onclick
 * @description 「상세내용 닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closeDetail_onclick = function(e){
    try {
        closeDetail(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst33011.btn_closeDetail_onclick' }); }
};
